<div class="d-flex justify-content-between flex-wrap gap-3 mb-4"><h1 class="h2">Membership application review</h1></div><div class="row g-3 mb-4"><?php foreach($counts as $key=>$count):?><div class="col-6 col-lg-3"><div class="card"><div class="card-body"><div class="text-secondary"><?=e($statuses->label($key))?></div><div class="display-6"><?=e($count)?></div></div></div></div><?php endforeach;?></div>
<form class="card card-body mb-4" method="get"><div class="row g-3"><div class="col-md-5"><label class="form-label" for="q">Reference, name or email</label><input class="form-control" id="q" name="q" maxlength="255" value="<?=e($search)?>"></div><div class="col-md-4"><label class="form-label" for="status_filter">Status</label><select class="form-select" id="status_filter" name="status"><option value="">All statuses</option><?php foreach(Ishep\Services\MembershipApplicationStatus::ALL as $item):?><option value="<?=e($item)?>" <?=$filter===$item?'selected':''?>><?=e($statuses->label($item))?></option><?php endforeach;?></select></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-primary w-100">Filter</button></div></div></form>
<div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Reference</th><th>Applicant</th><th>Type</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php if(!$applications):?><tr><td colspan="6" class="text-center p-5">No matching applications.</td></tr><?php endif;?><?php foreach($applications as $application):?><tr><td><?=e($application['application_number'])?></td><td><?=e($application['name'])?><br><small><?=e($application['email'])?></small></td><td><?=e($application['membership_type_name'])?></td><td><?=e($statuses->label($application['status']))?></td><td><?=e(date('j M Y',strtotime($application['updated_at'])))?></td><td><a href="<?=e(url('/admin/membership-applications/'.$application['application_number']))?>">Review</a></td></tr><?php endforeach;?></tbody></table></div></div>
